  {
    path: "/first-answer",
    name: "body token with edit_key_hash (no editKeyHash)",
    body: (hashes) => ({
      token: TOKEN,
      edit_key_hash: hashes.freshHash,
      questionVersionId: "qv-1",
      value: 4,
